 p=Path(f'pc{n}/etc/bind'); p.mkdir(parents=True,exist_ok=True)
 name='root' if z=='.' else z
 (p/'named.conf').write_text('options {\\n    directory \"/var/cache/bind\";\\n    listen-on { any; };\\n    listen-on-v6 { none; };\\n    recursion no;\\n    allow-query { any; };\\n    allow-transfer { none; };\\n    dnssec-validation no;\\n};\\nzone \"'+z+'\" { type primary; file \"/etc/bind/db.'+name+'\"; };\\n')
 origin='.' if z=='.' else z+'.'
 lines=[f'"'$ORIGIN {origin}'"', '"'$TTL 3600'"',f'@ IN SOA {ns(z)} hostmaster.{\"root.\" if z==\".\" else z+\".\"} ( 2026103001 3600 900 604800 3600 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ip}']
 if z not in ('.','com','net'): lines.append(f'@ IN A {ip}')
 if z in ('example.com','service.com','lab.net','tools.net'):
  lines.extend([f'@ IN MX 10 mail.{z}.',f'mail IN A {ip}'])
 if z=='example.com': lines.append(f'www IN A {ip}')
 for child in children.get(z,[]):
  lines.extend([f'{child}. IN NS {ns(child)}',f'{ns(child)} IN A {lookup[child][1]}'])
 (p/('db.'+name)).write_text('\\n'.join(lines)+'\\n')
 startup=Path(f'pc{n}.startup'); startup.write_text(startup.read_text()+'\\n# Start the authoritative DNS server after networking is configured.\\nmkdir -p /var/cache/bind /run/named\\nnamed -4 -c /etc/bind/named.conf\\n')
