    listen-on-v6 { none; };
    recursion yes;
    allow-query { any; };
    allow-recursion { 127.0.0.1; 10.14.5.0/24; 10.14.6.0/24; };
    allow-query-cache { 127.0.0.1; 10.14.5.0/24; 10.14.6.0/24; };
    dnssec-validation no;
    empty-zones-enable no;
};
zone \".\" { type hint; file \"/etc/bind/root.hints\"; };
''')
(p/'root.hints').write_text('. 3600000 IN NS ns.root.\\nns.root. 3600000 IN A 10.14.1.11\\n')
p=Path('pc14.startup'); p.write_text(p.read_text()+'\\n# Start the recursive resolver with the laboratory root hints.\\nmkdir -p /var/cache/bind /run/named\\nnamed -4 -c /etc/bind/named.conf\\n')
for n in range(16,21):
 p=Path(f'pc{n}.startup'); p.write_text(p.read_text()+\"\\n# Use the laboratory recursive resolver.\\nprintf 'nameserver 10.14.4.14\\\\n' > /etc/resolv.conf\\n\")
p=Path('pc4/var/www/html'); p.mkdir(parents=True,exist_ok=True)
(p/'index.html').write_text('<"'!doctype html>'"\\n<html lang=\"en\"><head><meta charset=\"utf-8\"><title>example.com</title></head><body><h1>Welcome to example.com</h1></body></html>\\n')
p=Path('pc4.startup'); p.write_text(p.read_text()+'\\n# Serve the example.com web page.\\npython3 -m http.server 80 --bind 0.0.0.0 --directory /var/www/html > /var/log/example-http.log 2>&1 &\\n')
