/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
zones={1:'.',2:'com',3:'net',4:'example.com',5:'service.com',6:'lab.net',7:'tools.net',8:'shop.example.com',9:'api.service.com',10:'research.lab.net',11:'ci.tools.net',12:'ai.research.lab.net',13:'data.research.lab.net'}
ips={1:'10.14.1.11',2:'10.14.1.12',3:'10.14.1.13',4:'10.14.1.14',5:'10.14.2.11',6:'10.14.2.12',7:'10.14.2.13',8:'10.14.3.11',9:'10.14.3.12',10:'10.14.3.13',11:'10.14.4.11',12:'10.14.4.12',13:'10.14.4.13'}
for n,z in zones.items():
 db=Path(f'pc{n}/etc/bind/db.'+('root' if z=='.' else z)).read_text()
 assert ' IN SOA ' in db and '@ IN NS ' in db
 if n>1:
  parent='.' if n in (2,3) else z.split('.',1)[1]
  pn=next(i for i,name in zones.items() if name==parent)
  parentdb=Path(f'pc{pn}/etc/bind/db.'+('root' if parent=='.' else parent)).read_text()
  assert f'{z}. IN NS ns.{z}.' in parentdb
  assert f'ns.{z}. IN A {ips[n]}' in parentdb
for n in (4,5,6,7):
 z=zones[n]; db=Path(f'pc{n}/etc/bind/db.{z}').read_text()
 assert f'@ IN MX 10 mail.{z}.' in db and f'mail IN A {ips[n]}' in db
for n in range(16,21): assert 'nameserver 10.14.4.14' in Path(f'pc{n}.startup').read_text()
print('Verified 13 SOA/NS pairs, 12 delegations and glue records, 4 MX records, and 5 client settings.')
PY"

